"""Shared metadata binding emitter. No source classification or key projection."""
import json
from pathlib import Path
import collect_catalogue as c
KEY_SHA='fe0a7272d6e372eefd4710b86f502e8c666fa5dfe8d1a17cc06df5e25deb0d95'
def emit_case(root,output,inputs,observations,diplomatic,peer_view,agreement_view,review_source,approved,profiles,counts,ids,provenance,audit_ref):
 c.require(not output.exists(),'New derived metadata directory required');output.mkdir(parents=True)
 def emit(name,data):
  p=output/name;p.write_bytes(c.json_bytes(data));return {'path':str(p.relative_to(root)),'sha256':c.sha(p)}
 def freeze(name,role,subject):return emit(name,{'schema':'anna-completion-freeze-v1','role':role,'subject_sha256':subject['sha256'],'key_projection_performed':False,'operation':'Derived metadata binding after frozen source comparison; not a new independent observation or retrospective preregistration.'})
 observations_ref=emit('observations-view.json',observations);dip_ref=emit('diplomatic-view.json',diplomatic);peer_ref=emit('peer-view.json',peer_view);peer_freeze=freeze('peer-view-freeze.json','peer',peer_ref);agreement_ref=emit('agreement-view.json',agreement_view);audit_freeze=freeze('audit-view-freeze.json','audit',audit_ref);nom_ref=inputs['nominations'];nom_freeze=freeze('nominations-view-freeze.json','nominations',nom_ref)
 ledgers=[p for face in profiles.values()for p in face['cipher_ledgers']]
 bindings={'protocol_sha256':inputs['protocol']['sha256'],'selection_sha256':inputs['selection']['sha256'],'face_observations_sha256':observations_ref['sha256'],'diplomatic_transcription_sha256':dip_ref['sha256'],'source_audit_sha256':audit_ref['sha256'],'source_audit_freeze_sha256':audit_freeze['sha256'],'fragment_nominations_sha256':nom_ref['sha256'],'fragment_nominations_freeze_sha256':nom_freeze['sha256'],'independent_fragments_sha256':peer_ref['sha256'],'independent_fragments_freeze_sha256':peer_freeze['sha256'],'fragment_agreement_sha256':agreement_ref['sha256'],'raw_ledgers_sha256':{p['scope_id']:p['ledger']['sha256']for p in ledgers},'raw_freezes_sha256':{p['scope_id']:p['freeze']['sha256']for p in ledgers},'row_region_bindings_sha256':{p['scope_id']:p['regions']['sha256']for p in ledgers}}
 review=emit('review-binding.json',{'card':inputs['card_id'],'bindings':bindings,'ordinary_transcription_scope':{name+'_records':counts[name]for name in counts},'proposed_additional_masks':approved,'fragment_group_boundary_warnings':review_source['fragment_warnings'],'ordinary_transcription_warnings':review_source['ordinary_warnings'],'complete_nomination_ids':ids,'preprojection_provenance':provenance,'source_review_mode':review_source['mode'],'normalization':'Original source classes/windows/order/ordinary strings unchanged. This is a hash-bound metadata view.'})
 review_freeze=freeze('review-binding-freeze.json','review',review)
 selection=json.loads((root/inputs['selection']['path']).read_text());overlay_records=[{**{k:v for k,v in r.items()if k!='bbox_xyxy'},'raw_bbox_xyxy':r['bbox_xyxy'],'action':'mask'}for r in approved]
 overlay=emit('exact-mask-overlay.json',{'schema':'anna-exact-unit-review-mask-v1','card':inputs['card_id'],'raw_ledgers_sha256':bindings['raw_ledgers_sha256'],'key_sha256':KEY_SHA,'source_review_sha256':review['sha256'],'source_faces_sha256':{f['face']:f['sha256']for f in selection['faces']},'action':'mask_exact_reviewed_units_no_class_or_literal_replacement','records':overlay_records})
 case={'schema':'anna-released-completion-case-v1','card_id':inputs['card_id'],'protocol':inputs['protocol'],'selection':inputs['selection'],'observations':observations_ref,'diplomatic':dip_ref,'review':review,'review_freeze':review_freeze,'audit':audit_ref,'audit_freeze':audit_freeze,'nominations':nom_ref,'nominations_freeze':nom_freeze,'expected_nomination_ids':ids,'peer_graphics':peer_ref,'peer_freeze':peer_freeze,'agreement':agreement_ref,'overlay':overlay,'faces':profiles,'preprojection_provenance':provenance}
 return emit('case-manifest.json',case)
